**Implementation Pseudocode:**
```
def map(g):
    # Phase 1: Find first occurrence of each unique non-zero value
    first_occurrence = {}
    for i in range(len(g)):
        for j in range(len(g[0])):
            val = g[i][j]
            if val != 0 and val not in first_occurrence:
                first_occurrence[val] = (i, j)

    # Phase 2: Build value mapping based on first occurrence positions
    value_mapping = {}
    for val, (i, j) in first_occurrence.items():
        output_key = (i + j) % 3
        value_mapping[output_key] = val

    # Phase 3: Fill output grid using the mapping
    result = []
    for i in range(len(g)):
        row = []
        for j in range(len(g[0])):
            output_key = (i + j) % 3
            value = value_mapping.get(output_key, 0)
            row.append(value)
        result.append(row)

    return result
```

